import React, { useState } from 'react';
import { TextField, Button, Typography, Card, CardContent } from '@mui/material';

function RootCausePage() {
  const [testName, setTestName] = useState('');
  const [result, setResult] = useState(null);

  const handleAnalyze = async () => {
    const res = await fetch(`/api/root-cause/${encodeURIComponent(testName)}`);
    const data = await res.json();
    setResult(data);
  };

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Root Cause Analysis
      </Typography>
      <TextField
        label="Test Name"
        value={testName}
        onChange={(e) => setTestName(e.target.value)}
        fullWidth
        margin="normal"
      />
      <Button variant="contained" onClick={handleAnalyze} disabled={!testName}>
        Analyze
      </Button>
      {result && (
        <Card sx={{ marginTop: 3 }}>
          <CardContent>
            <Typography variant="h6">Root Cause</Typography>
            <Typography>{result.root_cause}</Typography>
            <Typography variant="h6" sx={{ marginTop: 2 }}>Evidence</Typography>
            <Typography>{result.evidence}</Typography>
            <Typography variant="h6" sx={{ marginTop: 2 }}>Recommendation</Typography>
            <Typography>{result.recommendation}</Typography>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

export default RootCausePage;
